 "content": "def transform(grid):
    # On a row containing a foreground run followed only by background,
    # recolor that suffix with 1. Rows with mixed later foreground are unchanged.
    out = [row[:] for row in grid]
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = next((v for v in counts if v != bg), None)
    if fg is None:
        return out
    for r, row in enumerate(grid):
        if row[0] != fg:
            continue
        end = 0
        while end < len(row) and row[end] == fg:
            end += 1
        if end < len(row) and all(v == bg for v in row[end:]):
            for c in range(end, len(row)):
                out[r][c] = 1
    return out
